head.script:

	scwin.onpageload = function() {
		var jsonData = [
		    {
		        "col1": "즐겨찾기",
		        "col2": "1",
		        "col3": "1"
		    },
		    {
		        "col1": "테스트1(즐겨찾기)",
		        "col2": "2",
		        "col3": "2"
		    },
		    {
		        "col1": "테스트2(즐겨찾기)",
		        "col2": "3",
		        "col3": "2"
		    }			
		]


		dataList1.setJSON( jsonData );
	};

	scwin.onpageunload = function() {

	};


	scwin.trigger1_onclick = function(e) {
		var tmpStr = "<list>"; 
		tmpStr += "<map>"; 
        tmpStr += "<col1>테스트3(즐겨찾기)</col1>"; 
        tmpStr += "<col2>4</col2>"; 
        tmpStr += "<col3>2</col3>"; 
        tmpStr += "</map>"; 
    	tmpStr += "</list>"; 

    	var tmpDoc = WebSquare.xml.parse(tmpStr); 
		//3.5 appendXmlNodes에 사용할 파라메터 (XML Array) 생성 

		var tmpDocArr = WebSquare.xml.findNodes(tmpDoc,"list/map");

		//3.6 선택 된 노드에 추가. 
		var parentNode = treeview1.findNodeByValue("1");
		treeview1.appendXmlNodes( parentNode , tmpDocArr );
	};

	scwin.checkVal1 = function() {
		return WebSquare.wUnit.getDomById('treeview1_label_4').innerText == '테스트3(즐겨찾기)';
	}	
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
		WebSquare.wUnit.addCommand("pause", "400");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
		WebSquare.wUnit.addCommand("pause", "500");

		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}	
	scwin.unitTest()
